import React, { useState } from 'react';
import { Card, Spinner } from 'react-bootstrap';
import axios from 'axios';

function Terminal() {
  const [output, setOutput] = useState([
    { text: 'CoreX OS Terminal', type: 'system' },
    { text: 'Type "help" for available commands', type: 'system' },
    { text: '', type: 'normal' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleCommand = async (cmd) => {
    if (!cmd.trim()) return;
    
    // Add command to output (green)
    const newOutput = [...output, { text: `CoreX> ${cmd}`, type: 'command' }];
    setOutput(newOutput);
    setInput('');
    
    // Handle local commands
    if (cmd.trim() === 'clear') {
      setOutput([
        { text: 'CoreX OS Terminal', type: 'system' },
        { text: '', type: 'normal' }
      ]);
      return;
    }
    
    // Send command to backend
    setLoading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/shell/execute', {
        command: cmd
      });
      
      // Add response to output (white/cyan for output)
      if (response.data.output) {
        const outputLines = response.data.output.split('\n');
        const formattedOutput = outputLines.map(line => ({ text: line, type: 'output' }));
        setOutput([...newOutput, ...formattedOutput, { text: '', type: 'normal' }]);
      } else if (response.data.error) {
        setOutput([...newOutput, 
          { text: `Error: ${response.data.error}`, type: 'error' },
          { text: '', type: 'normal' }
        ]);
      } else {
        setOutput([...newOutput, 
          { text: 'Command executed successfully', type: 'output' },
          { text: '', type: 'normal' }
        ]);
      }
    } catch (error) {
      console.error('Error executing command:', error);
      setOutput([...newOutput, 
        { text: 'Error: Could not connect to backend', type: 'error' },
        { text: 'Make sure the Flask server is running on http://localhost:5000', type: 'error' },
        { text: 'Note: Terminal commands require the C core to be running', type: 'error' },
        { text: '', type: 'normal' }
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card>
      <Card.Header>
        <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
          <span>Terminal</span>
          {loading && <Spinner animation="border" size="sm" />}
        </div>
      </Card.Header>
      <Card.Body>
        <div className="terminal" style={{
          backgroundColor: '#1e1e1e',
          color: '#ffffff',
          fontFamily: 'Consolas, monospace',
          padding: '10px',
          minHeight: '400px',
          maxHeight: '600px',
          overflowY: 'auto',
          borderRadius: '4px'
        }}>
          {output.map((line, i) => {
            let color = '#ffffff'; // default white
            if (line.type === 'command') color = '#00ff00'; // green for commands
            else if (line.type === 'output') color = '#00d4ff'; // cyan for output
            else if (line.type === 'error') color = '#ff5555'; // red for errors
            else if (line.type === 'system') color = '#ffff00'; // yellow for system messages
            
            return (
              <div key={i} style={{whiteSpace: 'pre-wrap', color: color}}>
                {line.text}
              </div>
            );
          })}
          <div style={{display: 'flex', alignItems: 'center'}}>
            <span style={{color: '#00ff00'}}>CoreX&gt; </span>
            <input
              style={{
                backgroundColor: 'transparent',
                border: 'none',
                color: '#00ff00',
                fontFamily: 'Consolas, monospace',
                outline: 'none',
                flex: 1,
                marginLeft: '5px'
              }}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') handleCommand(input);
              }}
              disabled={loading}
              autoFocus
            />
          </div>
        </div>
      </Card.Body>
    </Card>
  );
}

export default Terminal;
